import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"General","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/general.md","filePath":"user-guide/settings/general.md","lastUpdated":1783439619000}'),o={name:"user-guide/settings/general.md"};function n(s,e,l,h,d,g){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h1><p>Four tabs: <strong>System</strong>, <strong>Search Bar Layout</strong>, <strong>Preview</strong>, and <strong>Search Window</strong>.</p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><ul><li><strong>Start SwiftList with Windows</strong> — checkbox, launches SwiftList at sign-in.</li><li><strong>Run as Administrator</strong> — checkbox, only enabled if the current user account is an administrator. Elevating SwiftList avoids the global hotkey being blocked by other elevated (as-admin) foreground applications.</li><li><strong>Auto check for updates on startup</strong> — checkbox.</li><li><strong>Auto silent update when a new version is detected</strong> — checkbox, only enabled while the check above is on; downloads and installs updates in the background without prompting.</li><li><strong>Log level</strong> — dropdown: Error / Warn / Info (default) / Debug. Controls verbosity across the App, Service, and Hook logs (see <a href="./service-status.html">Service Status</a>).</li><li><strong>Interface language</strong> — dropdown, populated from every installed translation provider (built-in languages plus any a plugin adds).</li><li><strong>Interface theme</strong> — dropdown: Light, Dark, Nord, Sakura, Cyberpunk (more can be added by theme plugins).</li></ul><h2 id="search-bar-layout" tabindex="-1">Search Bar Layout <a class="header-anchor" href="#search-bar-layout" aria-label="Permalink to &quot;Search Bar Layout&quot;">​</a></h2><p>Customizes the size, corner rounding, and on-screen position of the quick search bar:</p><ul><li><strong>Search Bar Width (px)</strong></li><li><strong>Search Bar Height (px)</strong> — default 70px. This one number also drives the overall UI scale factor (<code>height / 70</code>) for result-row icons and fonts, so a taller search bar scales the whole result list up with it.</li><li><strong>Corner Radius (px)</strong></li><li><strong>Result Icon Size (px)</strong> — range 16–64px, default 42px. Result name/path font size scales with this (with a legibility floor), independent of the search bar height above.</li><li><strong>Reset Layout Settings</strong> button — restores all four values to their defaults.</li></ul><p>Right-clicking the status icon inside the quick window&#39;s search box resets just its on-screen position (not size), re-centering it the same way it centers on first launch.</p><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h2><ul><li><strong>Preview Width (px)</strong> — range 250–900px.</li><li><strong>Preview Height (px)</strong> — range 250–1200px, default sized so the pane isn&#39;t overly tall on a typical display.</li><li><strong>Reset Preview Window Settings</strong> button.</li></ul><p>The preview window ignores the current result count — it&#39;s a fixed size, not a size that grows with content. See <a href="./../actions-and-preview.html">Actions Menu &amp; Preview</a> for how the pane is positioned.</p><h2 id="search-window" tabindex="-1">Search Window <a class="header-anchor" href="#search-window" aria-label="Permalink to &quot;Search Window&quot;">​</a></h2><p>Sets the default size of the full/main search window (the larger window you get from the taskbar or Start Menu shortcut, as opposed to the quick popup — see <a href="./../getting-started.html#the-three-windows">Getting Started</a>):</p><ul><li><strong>Window Width (px)</strong> — range 640–2000px, default 854px.</li><li><strong>Window Height (px)</strong> — range 400–1400px, default 480px. The minimums match the window&#39;s own resize floor, so a configured value is never silently overridden by the window itself.</li><li><strong>Reset Search Window Settings</strong> button.</li></ul><p>Dragging the window&#39;s edge to resize it manually is remembered automatically — the next time you open the window (or open a new one), it comes back at whatever size you last left it at, and this page&#39;s fields update to match. Resizing while maximized doesn&#39;t overwrite the remembered size; only resizing in the normal (non-maximized) state does.</p>',15)])])}const p=t(o,[["render",n]]);export{c as __pageData,p as default};
